public final class RemainingRuntime {
 public static final net.minecraft.world.level.block.entity.BlockEntityType<com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity> DREAM=Registry.register(BuiltInRegistries.BLOCK_ENTITY_TYPE,Catalog.id("dreamcatcher"),net.minecraft.world.level.block.entity.BlockEntityType.Builder.of(com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity::new,CatalogBlocks.DREAMCATCHER,CatalogBlocks.PURIFIED_DREAMCATCHER).build(null));
 public static final Holder<net.minecraft.world.effect.MobEffect> CONSECRATION=Registry.registerForHolder(BuiltInRegistries.MOB_EFFECT,Catalog.id("consecration"),new com.howierux.mortalexpansion.effect.ConsecrationEffect());
 public static final Holder<net.minecraft.world.item.alchemy.Potion> HOLY_POTION=Registry.registerForHolder(BuiltInRegistries.POTION,Catalog.id("holy_water"),new net.minecraft.world.item.alchemy.Potion("mortal_expansion.holy_water",new net.minecraft.world.effect.MobEffectInstance(CONSECRATION,1)));
 public static final net.fabricmc.fabric.api.attachment.v1.AttachmentType<net.minecraft.nbt.CompoundTag> ABILITIES=net.fabricmc.fabric.api.attachment.v1.AttachmentRegistry.create(Catalog.id("damned_abilities"),b->b.initializer(net.minecraft.nbt.CompoundTag::new).persistent(net.minecraft.nbt.CompoundTag.CODEC).copyOnDeath());
 public static final Holder<net.minecraft.world.effect.MobEffect> SANCTIFIED=Registry.registerForHolder(BuiltInRegistries.MOB_EFFECT,Catalog.id("sanctified"),new com.howierux.mortalexpansion.effect.SanctifiedEffect());
 public static void initialize(){
  net.fabricmc.fabric.api.transfer.v1.fluid.CauldronFluidContent.registerCauldron(CatalogBlocks.LIQUID_ECTOPLASM_CAULDRON,CatalogFluids.LIQUID_ECTOPLASM.source,net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,null);
  net.fabricmc.fabric.api.transfer.v1.fluid.CauldronFluidContent.registerCauldron(CatalogBlocks.HOLY_WATER_CAULDRON,CatalogFluids.HOLY_WATER.source,net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,null);
  net.fabricmc.fabric.api.transfer.v1.fluid.CauldronFluidContent.registerCauldron(CatalogBlocks.PURIFIED_ECTOPLASM_CAULDRON,CatalogFluids.PURIFIED_ECTOPLASM.source,net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants.BUCKET,null);

  ServerChunkEvents.CHUNK_LOAD.register(com.howierux.mortalexpansion.sanctification.SanctifiedAreaHandler::load);ServerChunkEvents.CHUNK_UNLOAD.register(com.howierux.mortalexpansion.sanctification.SanctifiedAreaHandler::unload);ServerWorldEvents.UNLOAD.register((server,level)->com.howierux.mortalexpansion.sanctification.SanctifiedAreaHandler.clear(level));

  net.fabricmc.fabric.api.entity.event.v1.EntitySleepEvents.ALLOW_SLEEP_TIME.register((p,pos,vanilla)->p instanceof net.minecraft.server.level.ServerPlayer s&&com.howierux.mortalexpansion.guide.DamnedAbilities.canDaySleep(s)?net.minecraft.world.InteractionResult.SUCCESS:net.minecraft.world.InteractionResult.PASS);
  net.fabricmc.fabric.api.entity.event.v1.EntitySleepEvents.ALLOW_RESETTING_TIME.register(p->!(p.level() instanceof net.minecraft.server.level.ServerLevel level&&com.howierux.mortalexpansion.guide.DamnedAbilities.dayVote(level)&&Math.floorMod(level.getDayTime(),24000)<12000));
  ServerTickEvents.END_WORLD_TICK.register(level->{for(var p:level.players())com.howierux.mortalexpansion.guide.DamnedAbilities.tick(p);com.howierux.mortalexpansion.guide.DamnedAbilities.levelTick(level);});
  net.fabricmc.fabric.api.event.player.UseItemCallback.EVENT.register((p,world,hand)->{var stack=p.getItemInHand(hand);if(stack.is(net.minecraft.world.item.Items.DIAMOND)&&com.howierux.mortalexpansion.guide.DamnedAbilities.active(p,com.howierux.mortalexpansion.guide.DamnedSecret.GREED)){p.startUsingItem(hand);return net.minecraft.world.InteractionResultHolder.consume(stack);}return net.minecraft.world.InteractionResultHolder.pass(stack);});
  net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.AFTER_DAMAGE.register((entity,source,base,taken,blocked)->{if(taken>0&&entity instanceof net.minecraft.server.level.ServerPlayer p)com.howierux.mortalexpansion.guide.DamnedAbilities.wrath(p);});
  net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.AFTER_DEATH.register((entity,source)->{if(source.getEntity() instanceof net.minecraft.server.level.ServerPlayer p)com.howierux.mortalexpansion.guide.DamnedAbilities.wrath(p);});
  ServerPlayConnectionEvents.DISCONNECT.register((handler,server)->com.howierux.mortalexpansion.guide.DamnedAbilities.logout(handler.player));ServerLifecycleEvents.SERVER_STOPPED.register(server->com.howierux.mortalexpansion.guide.DamnedAbilities.stopped());
  PayloadTypeRegistry.playC2S().register(com.howierux.mortalexpansion.network.EnvyPayloads.Request.TYPE,com.howierux.mortalexpansion.network.EnvyPayloads.Request.CODEC);PayloadTypeRegistry.playS2C().register(com.howierux.mortalexpansion.network.EnvyPayloads.View.TYPE,com.howierux.mortalexpansion.network.EnvyPayloads.View.CODEC);ServerPlayNetworking.registerGlobalReceiver(com.howierux.mortalexpansion.network.EnvyPayloads.Request.TYPE,(payload,context)->context.server().execute(()->com.howierux.mortalexpansion.network.EnvyPayloads.inspect(context.player(),payload.target())));

  ServerChunkEvents.CHUNK_LOAD.register((level,chunk)->{for(var e:chunk.getBlockEntities().values()){if(e instanceof com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity d)com.howierux.mortalexpansion.haunt.Dreamcatchers.add(level,e.getBlockPos(),d.owner());if(e instanceof com.howierux.mortalexpansion.travel.GraveEntity)com.howierux.mortalexpansion.spiritwell.GravePorting.loaded(level,e.getBlockPos());}});
  ServerChunkEvents.CHUNK_UNLOAD.register((level,chunk)->{for(var e:chunk.getBlockEntities().values()){if(e instanceof com.howierux.mortalexpansion.blockentity.DreamcatcherBlockEntity)com.howierux.mortalexpansion.haunt.Dreamcatchers.remove(level,e.getBlockPos());if(e instanceof com.howierux.mortalexpansion.travel.GraveEntity)com.howierux.mortalexpansion.spiritwell.GravePorting.unloaded(level,e.getBlockPos());}});
  net.fabricmc.fabric.api.entity.event.v1.EntitySleepEvents.ALLOW_NEARBY_MONSTERS.register((p,pos,vanilla)->p instanceof net.minecraft.server.level.ServerPlayer s&&com.howierux.mortalexpansion.haunt.Dreamcatchers.active(s)?net.minecraft.world.InteractionResult.SUCCESS:net.minecraft.world.InteractionResult.PASS);
  net.fabricmc.fabric.api.event.player.UseBlockCallback.EVENT.register(Catalog.id("formation_after_checks"),com.howierux.mortalexpansion.haunt.NaturalPurificationHandler::interact);
  PayloadTypeRegistry.playS2C().register(com.howierux.mortalexpansion.network.GravePortPayloads.Open.TYPE,com.howierux.mortalexpansion.network.GravePortPayloads.Open.CODEC);PayloadTypeRegistry.playC2S().register(com.howierux.mortalexpansion.network.GravePortPayloads.Choose.TYPE,com.howierux.mortalexpansion.network.GravePortPayloads.Choose.CODEC);ServerPlayNetworking.registerGlobalReceiver(com.howierux.mortalexpansion.network.GravePortPayloads.Choose.TYPE,(payload,context)->context.server().execute(()->com.howierux.mortalexpansion.spiritwell.GravePorting.choose(context.player(),payload.token(),payload.index())));
 }
}
